package com.cheatprogram.core;
import com.cheatprogram.core.setting.*;import com.cheatprogram.module.visual.*;import com.cheatprogram.module.world.BuildingBlueprints;import com.cheatprogram.util.*;import com.google.gson.*;import net.minecraft.nbt.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Feature-specific snapshots and a validate-before-mutate import boundary. */
public final class FeaturePresets {
 private static final Gson GSON=new Gson();private static final int MAX_BLOCKS=262144;
 public record Snapshot(ScopedPresetCodec.Scope scope,JsonObject data,String modelId){}
 public record Prepared(ScopedPresetCodec.Decoded decoded,ParticleStudio.Project particles,BuildingFiles.Blueprint building){}
 private FeaturePresets(){}
 public static Snapshot capture(ScopedPresetCodec.Scope scope)throws IOException{
  Module module=module(scope);JsonObject data=new JsonObject(),settings=new JsonObject();for(Setting<?> setting:module.settings())if(portable(setting))settings.add(setting.id,setting.save().deepCopy());data.add("settings",settings);
  if(scope==ScopedPresetCodec.Scope.MODEL){double norm=0;for(String key:List.of("offsetX","offsetY","offsetZ"))if(settings.has(key)){double v=settings.get(key).getAsDouble();norm+=v*v;}if(norm>16){double factor=4/Math.sqrt(norm);for(String key:List.of("offsetX","offsetY","offsetZ"))if(settings.has(key))settings.addProperty(key,settings.get(key).getAsDouble()*factor);}}
  if(scope==ScopedPresetCodec.Scope.PARTICLES){JsonObject project=GSON.toJsonTree(ParticleStudio.project()).getAsJsonObject();for(JsonElement round:project.getAsJsonArray("rounds"))for(JsonElement row:round.getAsJsonObject().getAsJsonArray("emitters")){JsonObject e=row.getAsJsonObject();for(String key:List.of("world","dimension"))e.addProperty(key,"");for(String key:List.of("anchorX","anchorY","anchorZ"))e.addProperty(key,0);e.addProperty("fixed",false);}data.add("project",project);}
  if(scope==ScopedPresetCodec.Scope.BUILDING){BuildingFiles.Blueprint building=((BuildingBlueprints)module).loaded();if(building==null)throw ScopedPresetCodec.bad("assetMissing");data.add("building",buildingJson(building));}
  String id=scope==ScopedPresetCodec.Scope.MODEL?((ModelWear)module).asset():"";return new Snapshot(scope,data,id);
 }
 public static String encode(Snapshot snapshot)throws IOException{Map<String,byte[]> assets=snapshot.scope==ScopedPresetCodec.Scope.MODEL?Map.of("model.cpmodel",WearModelStore.bytes(snapshot.modelId)):Map.of();return ScopedPresetCodec.encode(snapshot.scope,snapshot.data,assets);}
 public static Prepared validate(ScopedPresetCodec.Decoded decoded)throws IOException{
  Module module=module(decoded.scope());JsonObject settings=decoded.data().getAsJsonObject("settings");Map<String,Setting<?>> known=new HashMap<>();for(Setting<?> s:module.settings())if(portable(s))known.put(s.id,s);
  for(var entry:settings.entrySet()){Setting<?> setting=known.get(entry.getKey());if(setting==null)throw ScopedPresetCodec.bad("wrongScope");validateSetting(setting,entry.getValue());}
  if(decoded.scope()==ScopedPresetCodec.Scope.MODEL){double norm=0;for(String key:List.of("offsetX","offsetY","offsetZ")){double value=settings.has(key)?settings.get(key).getAsDouble():0;norm+=value*value;}if(norm>16.000001)throw ScopedPresetCodec.bad("invalid");}
  ParticleStudio.Project project=null;BuildingFiles.Blueprint building=null;if(decoded.scope()==ScopedPresetCodec.Scope.PARTICLES)project=particles(decoded.data().getAsJsonObject("project"));if(decoded.scope()==ScopedPresetCodec.Scope.BUILDING)building=building(decoded.data().getAsJsonObject("building"));return new Prepared(decoded,project,building);
 }
 /** Called on the worker only after every setting and complete payload passed validation. */
 public static String install(Prepared p)throws IOException{if(!Config.persistenceAllowed())throw ScopedPresetCodec.bad("saveFailed");return switch(p.decoded.scope()){case MODEL->WearModelStore.install(p.decoded.assets().get("model.cpmodel"));case BUILDING->BuildingFiles.save(p.building).name();default->"";};}
 /** Called on the client thread. This never changes another module or enables world-changing actions. */
 public static void apply(Prepared p,String asset)throws IOException{
  if(!Config.persistenceAllowed())throw ScopedPresetCodec.bad("saveFailed");Module module=module(p.decoded.scope());JsonObject settings=p.decoded.data().getAsJsonObject("settings");for(Setting<?> s:module.settings())if(settings.has(s.id))s.load(settings.get(s.id));
  switch(p.decoded.scope()){case MODEL->((ModelWear)module).asset(asset);case PARTICLES->{var project=ParticleStudio.project();project.rounds.clear();project.rounds.addAll(p.particles.rounds);project.version=2;ParticleStudio.touch();ParticleStudio.flush(true);((ParticleEffects)module).restart();}case BUILDING->((BuildingBlueprints)module).load(asset);default->{}}Config.markDirty();
 }
 private static Module module(ScopedPresetCodec.Scope scope)throws IOException{Module module=ModuleManager.byId(scope.module);if(module==null)throw ScopedPresetCodec.bad("wrongScope");return module;}
 private static boolean portable(Setting<?> s){return s instanceof BoolSetting||s instanceof NumberSetting||s instanceof ModeSetting;}
 private static void validateSetting(Setting<?> s,JsonElement value)throws IOException{
  if(value==null||!value.isJsonPrimitive())throw ScopedPresetCodec.bad("invalid");JsonPrimitive v=value.getAsJsonPrimitive();
  if(s instanceof BoolSetting){if(!v.isBoolean())throw ScopedPresetCodec.bad("invalid");}
  else if(s instanceof NumberSetting n){if(!v.isNumber())throw ScopedPresetCodec.bad("invalid");range(value,n.min,n.max);}
  else if(s instanceof ModeSetting m){if(!v.isString()||!m.modes.contains(v.getAsString()))throw ScopedPresetCodec.bad("invalid");}
 }
 private static ParticleStudio.Project particles(JsonObject json)throws IOException{
  if(json==null)throw ScopedPresetCodec.bad("invalid");ScopedPresetCodec.only(json,Set.of("version","rounds"));if(!json.has("rounds")||!json.get("rounds").isJsonArray())throw ScopedPresetCodec.bad("invalid");JsonArray rounds=json.getAsJsonArray("rounds");if(rounds.isEmpty()||rounds.size()>ParticleStudio.MAX_ROUNDS)throw ScopedPresetCodec.bad("tooLarge");int total=0;
  Set<String> emitterKeys=Set.of("id","particle","options","shown","fixed","rotateWithPlayer","world","dimension","symmetry","anchorX","anchorY","anchorZ","x","y","z","pitch","yaw","roll","vx","vy","vz","spread","scale","every","count","start","duration","lifetime","path");
  for(JsonElement item:rounds){if(!item.isJsonObject())throw ScopedPresetCodec.bad("invalid");JsonObject r=item.getAsJsonObject();ScopedPresetCodec.only(r,Set.of("id","name","duration","hold","emitters"));text(r,"name",80);range(r.get("duration"),1,72000);bool(r,"hold");JsonArray emitters=r.getAsJsonArray("emitters");if(emitters==null||emitters.size()>ParticleStudio.MAX_EMITTERS||(total+=emitters.size())>ParticleStudio.MAX_TOTAL)throw ScopedPresetCodec.bad("tooLarge");
   for(JsonElement value:emitters){if(!value.isJsonObject())throw ScopedPresetCodec.bad("invalid");JsonObject e=value.getAsJsonObject();ScopedPresetCodec.only(e,emitterKeys);if(!text(e,"particle",256).matches("[a-z0-9_.-]+:[a-z0-9_./-]+"))throw ScopedPresetCodec.bad("invalid");String options=text(e,"options",8192);if(options.contains("://")||options.toLowerCase(Locale.ROOT).contains("file:"))throw ScopedPresetCodec.bad("privateContent");for(String key:List.of("shown","fixed","rotateWithPlayer"))bool(e,key);if(e.get("fixed").getAsBoolean()||!text(e,"world",4096).isEmpty()||!text(e,"dimension",256).isEmpty())throw ScopedPresetCodec.bad("privateContent");if(!List.of("none","x","y","z","xy","xz","yz","xyz").contains(text(e,"symmetry",4)))throw ScopedPresetCodec.bad("invalid");
    for(String key:List.of("x","y","z"))range(e.get(key),-1024,1024);for(String key:List.of("pitch","yaw","roll"))range(e.get(key),-360,360);for(String key:List.of("vx","vy","vz"))range(e.get(key),-4,4);for(String key:List.of("anchorX","anchorY","anchorZ"))range(e.get(key),0,0);range(e.get("spread"),0,8);range(e.get("scale"),.05,8);for(String key:List.of("start","duration"))range(e.get(key),0,72000);range(e.get("every"),1,1200);range(e.get("count"),1,100);range(e.get("lifetime"),0,1200);
    if(e.has("path"))particlePath(e.get("path"));
   }
  }
  try{ParticleStudio.Project p=GSON.fromJson(json,ParticleStudio.Project.class);p.version=2;for(var r:p.rounds){r.id=UUID.randomUUID().toString();for(var e:r.emitters){e.id=UUID.randomUUID().toString();e.path=ParticlePath.sanitize(e.path);}}return p;}catch(RuntimeException e){throw ScopedPresetCodec.bad("invalid");}
 }
 private static void particlePath(JsonElement value)throws IOException{
  if(value==null||!value.isJsonObject())throw ScopedPresetCodec.bad("invalid");JsonObject p=value.getAsJsonObject();
  ScopedPresetCodec.only(p,Set.of("kind","loop","plane","interpolation","duration","radius","height","phase","nativeMotion","points","clock"));
  if(!ParticlePath.KINDS.contains(text(p,"kind",16))||!ParticlePath.LOOPS.contains(text(p,"loop",16))||!ParticlePath.PLANES.contains(text(p,"plane",4))||!ParticlePath.INTERPOLATIONS.contains(text(p,"interpolation",16)))throw ScopedPresetCodec.bad("invalid");
  if(p.has("clock")&&!ParticlePath.CLOCKS.contains(text(p,"clock",16)))throw ScopedPresetCodec.bad("invalid");
  range(p.get("duration"),1,72000);range(p.get("radius"),0,16);range(p.get("height"),-16,16);range(p.get("phase"),0,360);bool(p,"nativeMotion");
  JsonElement raw=p.get("points");if(raw==null||!raw.isJsonArray()||raw.getAsJsonArray().size()<2||raw.getAsJsonArray().size()>ParticlePath.MAX_POINTS)throw ScopedPresetCodec.bad("invalid");
  for(JsonElement element:raw.getAsJsonArray()){if(!element.isJsonObject())throw ScopedPresetCodec.bad("invalid");JsonObject point=element.getAsJsonObject();ScopedPresetCodec.only(point,Set.of("x","y","z"));for(String axis:List.of("x","y","z"))range(point.get(axis),-16,16);}
 }
 private static JsonObject buildingJson(BuildingFiles.Blueprint b)throws IOException{
  if(b.count()>MAX_BLOCKS)throw ScopedPresetCodec.bad("tooLarge");JsonObject result=new JsonObject();result.addProperty("name",b.name());JsonArray size=new JsonArray();size.add(b.width());size.add(b.height());size.add(b.depth());result.add("size",size);JsonArray palette=new JsonArray();for(CompoundTag tag:b.palette()){JsonObject state=new JsonObject();state.addProperty("Name",tag.getString("Name"));JsonObject properties=new JsonObject();CompoundTag stored=tag.getCompound("Properties");for(String key:stored.getAllKeys())properties.addProperty(key,stored.getString(key));state.add("Properties",properties);palette.add(state);}result.add("palette",palette);ByteBuffer blocks=ByteBuffer.allocate(b.count()*4);for(int block:b.blocks())blocks.putInt(block);result.addProperty("blocks",Base64.getEncoder().encodeToString(blocks.array()));return result;
 }
 private static BuildingFiles.Blueprint building(JsonObject json)throws IOException{
  if(json==null)throw ScopedPresetCodec.bad("assetMissing");ScopedPresetCodec.only(json,Set.of("name","size","palette","blocks"));String name=text(json,"name",100);if(!name.equals(BuildingFiles.cleanName(name)))throw ScopedPresetCodec.bad("invalid");JsonArray dimensions=json.getAsJsonArray("size");if(dimensions==null||dimensions.size()!=3)throw ScopedPresetCodec.bad("invalid");int w=integer(dimensions.get(0),1,1024),h=integer(dimensions.get(1),1,1024),d=integer(dimensions.get(2),1,1024);if((long)w*h*d>MAX_BLOCKS)throw ScopedPresetCodec.bad("tooLarge");JsonArray raw=json.getAsJsonArray("palette");if(raw==null||raw.isEmpty()||raw.size()>65536)throw ScopedPresetCodec.bad("invalid");List<CompoundTag> palette=new ArrayList<>();
  for(JsonElement item:raw){JsonObject state=item.getAsJsonObject();ScopedPresetCodec.only(state,Set.of("Name","Properties"));String id=text(state,"Name",256);if(!id.matches("[a-z0-9_.-]+:[a-z0-9_./-]+"))throw ScopedPresetCodec.bad("invalid");CompoundTag entry=new CompoundTag();entry.putString("Name",id);JsonObject properties=state.getAsJsonObject("Properties");if(properties==null||properties.size()>64)throw ScopedPresetCodec.bad("invalid");CompoundTag p=new CompoundTag();for(String key:properties.keySet()){if(!key.matches("[a-z0-9_]{1,64}"))throw ScopedPresetCodec.bad("invalid");String v=text(properties,key,100);if(!v.matches("[a-zA-Z0-9_.-]+"))throw ScopedPresetCodec.bad("invalid");p.putString(key,v);}entry.put("Properties",p);palette.add(entry);}
  byte[] encoded;try{encoded=Base64.getDecoder().decode(text(json,"blocks",MAX_BLOCKS*6));}catch(IllegalArgumentException e){throw ScopedPresetCodec.bad("invalid");}int count=w*h*d;if(encoded.length!=count*4)throw ScopedPresetCodec.bad("invalid");ByteBuffer buffer=ByteBuffer.wrap(encoded);int[] blocks=new int[count];for(int i=0;i<count;i++){blocks[i]=buffer.getInt();if(blocks[i]<0||blocks[i]>=palette.size())throw ScopedPresetCodec.bad("invalid");}return new BuildingFiles.Blueprint(name,w,h,d,List.copyOf(palette),blocks,Map.of());
 }
 private static String text(JsonObject o,String key,int max)throws IOException{JsonElement v=o.get(key);if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isString())throw ScopedPresetCodec.bad("invalid");String s=v.getAsString();if(s.length()>max||s.chars().anyMatch(Character::isISOControl))throw ScopedPresetCodec.bad("invalid");return s;}
 private static void bool(JsonObject o,String key)throws IOException{JsonElement v=o.get(key);if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isBoolean())throw ScopedPresetCodec.bad("invalid");}
 private static double range(JsonElement v,double min,double max)throws IOException{if(v==null||!v.isJsonPrimitive()||!v.getAsJsonPrimitive().isNumber())throw ScopedPresetCodec.bad("invalid");double n=v.getAsDouble();if(!Double.isFinite(n)||n<min||n>max)throw ScopedPresetCodec.bad("invalid");return n;}
 private static int integer(JsonElement v,int min,int max)throws IOException{double n=range(v,min,max);if(n!=Math.rint(n))throw ScopedPresetCodec.bad("invalid");return (int)n;}
}
